/**
 * Vendor page URLs: `/vendor/<slug>`, e.g. `/vendor/dj-blnce`.
 *
 * The slug is generated by the database on insert and never changes after
 * (migration 0052 has the rules), so the app only ever READS it. The vendor
 * page still accepts the old `/vendor/<uuid>` form and redirects it to the slug,
 * which keeps every link shared before slugs existed working.
 *
 * Build every vendor link through `vendorPath()` so there is one place that
 * knows the shape. It falls back to the id when a row has no slug in hand (a
 * caller that only selected `id`), which costs one redirect, never a 404.
 */

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** True when a `/vendor/[id]` path segment is a legacy uuid rather than a slug. */
export function isVendorUuid(ref: string): boolean {
  return UUID_RE.test(ref);
}

export interface VendorRef {
  id: string;
  slug?: string | null;
}

/**
 * The vendor page path, optionally with a `from` return path for its back
 * button (internal paths only; the page re-checks it).
 */
export function vendorPath(vendor: VendorRef, from?: string | null): string {
  const path = `/vendor/${vendor.slug || vendor.id}`;
  return from ? `${path}?from=${encodeURIComponent(from)}` : path;
}
